    COALESCE(try_to_date(trim(`decision_date`), 'yyyy-MM-dd'), try_to_date(trim(`decision_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`decision_date`) AS DATE)) AS `decision_date`,
