    NULLIF(trim(`decision_text`), '') AS `decision_text`,
    COALESCE(try_to_timestamp(trim(`decision_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`decision_timestamp`) AS TIMESTAMP)) AS `decision_timestamp`,
    NULLIF(trim(`defect_code`), '') AS `defect_code`,
    NULLIF(trim(`defect_description`), '') AS `defect_description`,
    COALESCE(try_to_date(trim(`disposition_date`), 'yyyy-MM-dd'), try_to_date(trim(`disposition_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`disposition_date`) AS DATE)) AS `disposition_date`,
    CASE lower(trim(`disposition_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'completed' THEN 'completed'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULLIF(trim(`disposition_status`), '')
    END AS `disposition_status`,
    CASE WHEN lower(trim(`gmp_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliance_flag`,
    CASE lower(trim(`inspection_type`))
      WHEN 'goods_receipt' THEN 'goods_receipt'
      WHEN 'in_process' THEN 'in_process'
      WHEN 'final' THEN 'final'
      WHEN 'stability' THEN 'stability'
      WHEN 'complaint' THEN 'complaint'
      ELSE NULLIF(trim(`inspection_type`), '')
    END AS `inspection_type`,
    NULLIF(trim(`plant_code`), '') AS `plant_code`,
    TRY_CAST(NULLIF(trim(`quantity_accepted`), '') AS DECIMAL(18,3)) AS `quantity_accepted`,
    TRY_CAST(NULLIF(trim(`quantity_rejected`), '') AS DECIMAL(18,3)) AS `quantity_rejected`,
    TRY_CAST(NULLIF(trim(`quantity_rework`), '') AS DECIMAL(18,3)) AS `quantity_rework`,
    COALESCE(try_to_timestamp(trim(`record_created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`record_created_timestamp`) AS TIMESTAMP)) AS `record_created_timestamp`,
    COALESCE(try_to_timestamp(trim(`record_updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`record_updated_timestamp`) AS TIMESTAMP)) AS `record_updated_timestamp`,
    CASE WHEN lower(trim(`regulatory_hold_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_hold_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_hold_flag`,
    NULLIF(trim(`regulatory_hold_reason`), '') AS `regulatory_hold_reason`,
    NULLIF(trim(`sampling_procedure`), '') AS `sampling_procedure`,
    NULLIF(trim(`source_system_code`), '') AS `source_system_code`,
    CASE lower(trim(`stock_posting_instruction`))
      WHEN 'unrestricted' THEN 'unrestricted'
      WHEN 'blocked' THEN 'blocked'
      WHEN 'quality_inspection' THEN 'quality_inspection'
      WHEN 'scrap' THEN 'scrap'
      WHEN 'sample' THEN 'sample'
      WHEN 'rework' THEN 'rework'
      ELSE NULLIF(trim(`stock_posting_instruction`), '')
    END AS `stock_posting_instruction`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.quality_usage_decision
)
SELECT *
FROM typed
QUALIFY `usage_decision_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `usage_decision_id` ORDER BY `record_updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- quality.nonconformance ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.quality_nonconformance (
  CONSTRAINT `nonconformance_id_not_null` EXPECT (`nonconformance_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: quality.nonconformance typed and cleaned, one row per nonconformance_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`nonconformance_id`), '') AS BIGINT) AS `nonconformance_id`,
    TRY_CAST(NULLIF(trim(`capa_id`), '') AS BIGINT) AS `capa_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`inbound_receipt_id`), '') AS BIGINT) AS `inbound_receipt_id`,
    TRY_CAST(NULLIF(trim(`inspection_lot_id`), '') AS BIGINT) AS `inspection_lot_id`,
    TRY_CAST(NULLIF(trim(`inventory_position_id`), '') AS BIGINT) AS `inventory_position_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`order_id`), '') AS BIGINT) AS `order_id`,
    TRY_CAST(NULLIF(trim(`product_complaint_id`), '') AS BIGINT) AS `product_complaint_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`purchase_order_id`), '') AS BIGINT) AS `purchase_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    TRY_CAST(NULLIF(trim(`affected_quantity`), '') AS DECIMAL(15,3)) AS `affected_quantity`,
    CASE lower(trim(`affected_quantity_uom`))
      WHEN 'ea' THEN 'EA'
      WHEN 'kg' THEN 'KG'
      WHEN 'l' THEN 'L'
      WHEN 'm' THEN 'M'
      WHEN 'box' THEN 'BOX'
      WHEN 'pallet' THEN 'PALLET'
      ELSE NULLIF(trim(`affected_quantity_uom`), '')
    END AS `affected_quantity_uom`,
    COALESCE(try_to_timestamp(trim(`closed_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`closed_timestamp`) AS TIMESTAMP)) AS `closed_timestamp`,
    NULLIF(trim(`containment_action`), '') AS `containment_action`,
    COALESCE(try_to_timestamp(trim(`containment_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`containment_timestamp`) AS TIMESTAMP)) AS `containment_timestamp`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`defect_classification`), '') AS `defect_classification`,
    NULLIF(trim(`defect_description`), '') AS `defect_description`,
    COALESCE(try_to_timestamp(trim(`detected_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`detected_timestamp`) AS TIMESTAMP)) AS `detected_timestamp`,
    NULLIF(trim(`detection_source`), '') AS `detection_source`,
    NULLIF(trim(`disposition_approved_by`), '') AS `disposition_approved_by`,
    COALESCE(try_to_timestamp(trim(`disposition_approved_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`disposition_approved_timestamp`) AS TIMESTAMP)) AS `disposition_approved_timestamp`,
    CASE lower(trim(`disposition_decision`))
      WHEN 'use_as_is' THEN 'use_as_is'
      WHEN 'rework' THEN 'rework'
      WHEN 'scrap' THEN 'scrap'
      WHEN 'return_to_supplier' THEN 'return_to_supplier'
      WHEN 'downgrade' THEN 'downgrade'
      WHEN 'quarantine' THEN 'quarantine'
      ELSE NULLIF(trim(`disposition_decision`), '')
    END AS `disposition_decision`,
    CASE lower(trim(`event_type`))
      WHEN 'complaint' THEN 'complaint'
      WHEN 'defect' THEN 'defect'
      WHEN 'deviation' THEN 'deviation'
      WHEN 'improvement_request' THEN 'improvement_request'
      WHEN 'supplier_issue' THEN 'supplier_issue'
      WHEN 'audit_finding' THEN 'audit_finding'
      ELSE NULLIF(trim(`event_type`), '')
    END AS `event_type`,
    TRY_CAST(NULLIF(trim(`financial_impact_amount`), '') AS DECIMAL(15,2)) AS `financial_impact_amount`,
    NULLIF(trim(`financial_impact_currency`), '') AS `financial_impact_currency`,
    CASE lower(trim(`nonconformance_status`))
      WHEN 'open' THEN 'open'
      WHEN 'in_investigation' THEN 'in_investigation'
      WHEN 'containment_active' THEN 'containment_active'
      WHEN 'capa_assigned' THEN 'capa_assigned'
      WHEN 'closed' THEN 'closed'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULLIF(trim(`nonconformance_status`), '')
    END AS `nonconformance_status`,
    NULLIF(trim(`notification_number`), '') AS `notification_number`,
    CASE lower(trim(`priority`))
      WHEN 'urgent' THEN 'urgent'
      WHEN 'high' THEN 'high'
      WHEN 'medium' THEN 'medium'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`priority`), '')
    END AS `priority`,
    COALESCE(try_to_date(trim(`regulatory_report_date`), 'yyyy-MM-dd'), try_to_date(trim(`regulatory_report_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`regulatory_report_date`) AS DATE)) AS `regulatory_report_date`,
    CASE WHEN lower(trim(`regulatory_reportable_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_reportable_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_reportable_flag`,
    COALESCE(try_to_timestamp(trim(`reported_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`reported_timestamp`) AS TIMESTAMP)) AS `reported_timestamp`,
    NULLIF(trim(`responsible_department`), '') AS `responsible_department`,
    NULLIF(trim(`responsible_plant_code`), '') AS `responsible_plant_code`,
    NULLIF(trim(`root_cause_analysis`), '') AS `root_cause_analysis`,
    CASE lower(trim(`severity`))
      WHEN 'critical' THEN 'critical'
      WHEN 'major' THEN 'major'
      WHEN 'minor' THEN 'minor'
      ELSE NULLIF(trim(`severity`), '')
    END AS `severity`,
    NULLIF(trim(`source_system_code`), '') AS `source_system_code`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    NULLIF(trim(`verification_method`), '') AS `verification_method`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.quality_nonconformance
)
SELECT *
FROM typed
QUALIFY `nonconformance_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `nonconformance_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- quality.capa ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.quality_capa (
  CONSTRAINT `capa_id_not_null` EXPECT (`capa_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: quality.capa typed and cleaned, one row per capa_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`capa_id`), '') AS BIGINT) AS `capa_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`inspection_lot_id`), '') AS BIGINT) AS `inspection_lot_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_date(trim(`actual_completion_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_completion_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_completion_date`) AS DATE)) AS `actual_completion_date`,
    NULLIF(trim(`batch_number`), '') AS `batch_number`,
    NULLIF(trim(`capa_number`), '') AS `capa_number`,
    NULLIF(trim(`capa_status`), '') AS `capa_status`,
    CASE lower(trim(`capa_type`))
      WHEN 'corrective' THEN 'corrective'
      WHEN 'preventive' THEN 'preventive'
      WHEN 'combined' THEN 'combined'
      ELSE NULLIF(trim(`capa_type`), '')
    END AS `capa_type`,
    NULLIF(trim(`closure_comments`), '') AS `closure_comments`,
    COALESCE(try_to_date(trim(`closure_date`), 'yyyy-MM-dd'), try_to_date(trim(`closure_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`closure_date`) AS DATE)) AS `closure_date`,
    NULLIF(trim(`corrective_action_description`), '') AS `corrective_action_description`,
    TRY_CAST(NULLIF(trim(`cost_impact_amount`), '') AS DECIMAL(18,2)) AS `cost_impact_amount`,
    NULLIF(trim(`cost_impact_currency_code`), '') AS `cost_impact_currency_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`customer_impact_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`customer_impact_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `customer_impact_flag`,
    NULLIF(trim(`description`), '') AS `description`,
    NULLIF(trim(`effectiveness_verification_method`), '') AS `effectiveness_verification_method`,
    CASE lower(trim(`effectiveness_verification_result`))
      WHEN 'effective' THEN 'effective'
      WHEN 'ineffective' THEN 'ineffective'
      WHEN 'pending' THEN 'pending'
      ELSE NULLIF(trim(`effectiveness_verification_result`), '')
    END AS `effectiveness_verification_result`,
    CASE WHEN lower(trim(`gmp_deviation_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_deviation_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_deviation_flag`,
    COALESCE(try_to_date(trim(`initiated_date`), 'yyyy-MM-dd'), try_to_date(trim(`initiated_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`initiated_date`) AS DATE)) AS `initiated_date`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`preventive_action_description`), '') AS `preventive_action_description`,
    CASE lower(trim(`priority`))
      WHEN 'high' THEN 'high'
      WHEN 'medium' THEN 'medium'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`priority`), '')
    END AS `priority`,
    NULLIF(trim(`process_area`), '') AS `process_area`,
    COALESCE(try_to_date(trim(`regulatory_report_date`), 'yyyy-MM-dd'), try_to_date(trim(`regulatory_report_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`regulatory_report_date`) AS DATE)) AS `regulatory_report_date`,
    CASE WHEN lower(trim(`regulatory_reportable_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_reportable_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_reportable_flag`,
    NULLIF(trim(`responsible_department`), '') AS `responsible_department`,
    CASE lower(trim(`root_cause_analysis_method`))
      WHEN '5_whys' THEN '5_whys'
      WHEN 'fishbone' THEN 'fishbone'
      WHEN 'fault_tree' THEN 'fault_tree'
      WHEN 'pareto' THEN 'pareto'
      WHEN 'failure_mode_effects_analysis' THEN 'failure_mode_effects_analysis'
      WHEN 'other' THEN 'other'
      ELSE NULLIF(trim(`root_cause_analysis_method`), '')
    END AS `root_cause_analysis_method`,
    NULLIF(trim(`root_cause_description`), '') AS `root_cause_description`,
    CASE lower(trim(`severity`))
      WHEN 'critical' THEN 'critical'
      WHEN 'major' THEN 'major'
      WHEN 'minor' THEN 'minor'
      ELSE NULLIF(trim(`severity`), '')
    END AS `severity`,
    NULLIF(trim(`source_reference_number`), '') AS `source_reference_number`,
    CASE lower(trim(`source_type`))
      WHEN 'nonconformance' THEN 'nonconformance'
      WHEN 'audit_finding' THEN 'audit_finding'
      WHEN 'customer_complaint' THEN 'customer_complaint'
      WHEN 'supplier_issue' THEN 'supplier_issue'
      WHEN 'stability_failure' THEN 'stability_failure'
      WHEN 'regulatory_inspection' THEN 'regulatory_inspection'
      ELSE NULLIF(trim(`source_type`), '')
    END AS `source_type`,
    COALESCE(try_to_date(trim(`target_completion_date`), 'yyyy-MM-dd'), try_to_date(trim(`target_completion_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`target_completion_date`) AS DATE)) AS `target_completion_date`,
    NULLIF(trim(`title`), '') AS `title`,
    COALESCE(try_to_date(trim(`verification_date`), 'yyyy-MM-dd'), try_to_date(trim(`verification_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`verification_date`) AS DATE)) AS `verification_date`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.quality_capa
)
SELECT *
FROM typed
QUALIFY `capa_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `capa_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- quality.batch_release ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.quality_batch_release (
  CONSTRAINT `batch_release_id_not_null` EXPECT (`batch_release_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: quality.batch_release typed and cleaned, one row per batch_release_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`batch_release_id`), '') AS BIGINT) AS `batch_release_id`,
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`certificate_of_analysis_id`), '') AS BIGINT) AS `certificate_of_analysis_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`formulation_id`), '') AS BIGINT) AS `formulation_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`inspection_lot_id`), '') AS BIGINT) AS `inspection_lot_id`,
    TRY_CAST(NULLIF(trim(`inventory_position_id`), '') AS BIGINT) AS `inventory_position_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`standard_cost_id`), '') AS BIGINT) AS `standard_cost_id`,
    TRY_CAST(NULLIF(trim(`usage_decision_id`), '') AS BIGINT) AS `usage_decision_id`,
    NULLIF(trim(`audit_trail_reference`), '') AS `audit_trail_reference`,
    TRY_CAST(NULLIF(trim(`batch_size_quantity`), '') AS DECIMAL(18,3)) AS `batch_size_quantity`,
    NULLIF(trim(`batch_size_uom`), '') AS `batch_size_uom`,
    CASE WHEN lower(trim(`capa_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`capa_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `capa_required_flag`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    TRY_CAST(NULLIF(trim(`deviation_count`), '') AS INT) AS `deviation_count`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    CASE WHEN lower(trim(`gmp_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliance_flag`,
    COALESCE(try_to_date(trim(`hold_initiated_date`), 'yyyy-MM-dd'), try_to_date(trim(`hold_initiated_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`hold_initiated_date`) AS DATE)) AS `hold_initiated_date`,
    NULLIF(trim(`hold_reason`), '') AS `hold_reason`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`manufacturing_site_code`), '') AS `manufacturing_site_code`,
    NULLIF(trim(`product_registration_number`), '') AS `product_registration_number`,
    COALESCE(try_to_date(trim(`production_date`), 'yyyy-MM-dd'), try_to_date(trim(`production_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`production_date`) AS DATE)) AS `production_date`,
    CASE lower(trim(`qc_inspection_status`))
      WHEN 'passed' THEN 'passed'
      WHEN 'failed' THEN 'failed'
      WHEN 'conditional_pass' THEN 'conditional_pass'
      WHEN 'pending' THEN 'pending'
      WHEN 'waived' THEN 'waived'
      ELSE NULLIF(trim(`qc_inspection_status`), '')
    END AS `qc_inspection_status`,
    COALESCE(try_to_timestamp(trim(`qp_signature_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`qp_signature_timestamp`) AS TIMESTAMP)) AS `qp_signature_timestamp`,
    NULLIF(trim(`qualified_person_name`), '') AS `qualified_person_name`,
    CASE lower(trim(`regulatory_hold_status`))
      WHEN 'no_hold' THEN 'no_hold'
      WHEN 'fda_hold' THEN 'fda_hold'
      WHEN 'epa_hold' THEN 'epa_hold'
      WHEN 'internal_hold' THEN 'internal_hold'
      WHEN 'customer_hold' THEN 'customer_hold'
      WHEN 'recall_hold' THEN 'recall_hold'
      ELSE NULLIF(trim(`regulatory_hold_status`), '')
    END AS `regulatory_hold_status`,
    NULLIF(trim(`regulatory_market`), '') AS `regulatory_market`,
    TRY_CAST(NULLIF(trim(`rejected_quantity`), '') AS DECIMAL(18,3)) AS `rejected_quantity`,
    COALESCE(try_to_date(trim(`release_date`), 'yyyy-MM-dd'), try_to_date(trim(`release_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`release_date`) AS DATE)) AS `release_date`,
    CASE lower(trim(`release_decision`))
      WHEN 'released' THEN 'released'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'quarantine' THEN 'quarantine'
      WHEN 'conditional_release' THEN 'conditional_release'
      WHEN 'pending_review' THEN 'pending_review'
      WHEN 'on_hold' THEN 'on_hold'
      ELSE NULLIF(trim(`release_decision`), '')
    END AS `release_decision`,
    NULLIF(trim(`release_notes`), '') AS `release_notes`,
    COALESCE(try_to_timestamp(trim(`release_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`release_timestamp`) AS TIMESTAMP)) AS `release_timestamp`,
    TRY_CAST(NULLIF(trim(`released_quantity`), '') AS DECIMAL(18,3)) AS `released_quantity`,
    COALESCE(try_to_date(trim(`retest_date`), 'yyyy-MM-dd'), try_to_date(trim(`retest_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`retest_date`) AS DATE)) AS `retest_date`,
    NULLIF(trim(`stability_study_reference`), '') AS `stability_study_reference`,
    NULLIF(trim(`veeva_vault_document_reference`), '') AS `veeva_vault_document_reference`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.quality_batch_release
)
SELECT *
FROM typed
QUALIFY `batch_release_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `batch_release_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- quality.certificate_of_analysis ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.quality_certificate_of_analysis (
  CONSTRAINT `certificate_of_analysis_id_not_null` EXPECT (`certificate_of_analysis_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: quality.certificate_of_analysis typed and cleaned, one row per certificate_of_analysis_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`certificate_of_analysis_id`), '') AS BIGINT) AS `certificate_of_analysis_id`,
    TRY_CAST(NULLIF(trim(`goods_receipt_id`), '') AS BIGINT) AS `goods_receipt_id`,
    TRY_CAST(NULLIF(trim(`inspection_lot_id`), '') AS BIGINT) AS `inspection_lot_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`specification_id`), '') AS BIGINT) AS `specification_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    COALESCE(try_to_timestamp(trim(`approval_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approval_timestamp`) AS TIMESTAMP)) AS `approval_timestamp`,
    NULLIF(trim(`authorized_signatory_name`), '') AS `authorized_signatory_name`,
    NULLIF(trim(`authorized_signatory_title`), '') AS `authorized_signatory_title`,
    NULLIF(trim(`batch_number`), '') AS `batch_number`,
    TRY_CAST(NULLIF(trim(`batch_size`), '') AS DECIMAL(18,3)) AS `batch_size`,
    CASE lower(trim(`batch_size_uom`))
      WHEN 'kg' THEN 'kg'
      WHEN 'g' THEN 'g'
      WHEN 'l' THEN 'L'
      WHEN 'ml' THEN 'mL'
      WHEN 'units' THEN 'units'
      WHEN 'cases' THEN 'cases'
      ELSE NULLIF(trim(`batch_size_uom`), '')
    END AS `batch_size_uom`,
    NULLIF(trim(`certificate_number`), '') AS `certificate_number`,
    CASE lower(trim(`certificate_type`))
      WHEN 'finished_goods' THEN 'finished_goods'
      WHEN 'raw_material' THEN 'raw_material'
      WHEN 'intermediate' THEN 'intermediate'
      WHEN 'packaging_material' THEN 'packaging_material'
      ELSE NULLIF(trim(`certificate_type`), '')
    END AS `certificate_type`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`customer_facing_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`customer_facing_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `customer_facing_flag`,
    NULLIF(trim(`document_url`), '') AS `document_url`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    CASE WHEN lower(trim(`gmp_compliant_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`gmp_compliant_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `gmp_compliant_flag`,
    COALESCE(try_to_date(trim(`issue_date`), 'yyyy-MM-dd'), try_to_date(trim(`issue_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`issue_date`) AS DATE)) AS `issue_date`,
    COALESCE(try_to_date(trim(`manufacturing_date`), 'yyyy-MM-dd'), try_to_date(trim(`manufacturing_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`manufacturing_date`) AS DATE)) AS `manufacturing_date`,
    NULLIF(trim(`material_code`), '') AS `material_code`,
    NULLIF(trim(`material_description`), '') AS `material_description`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    CASE lower(trim(`overall_result_status`))
      WHEN 'pass' THEN 'pass'
      WHEN 'fail' THEN 'fail'
      WHEN 'conditional_pass' THEN 'conditional_pass'
      WHEN 'pending_review' THEN 'pending_review'
      ELSE NULLIF(trim(`overall_result_status`), '')
    END AS `overall_result_status`,
    TRY_CAST(NULLIF(trim(`quantity_tested`), '') AS DECIMAL(18,3)) AS `quantity_tested`,
    CASE lower(trim(`quantity_tested_uom`))
      WHEN 'kg' THEN 'kg'
      WHEN 'g' THEN 'g'
      WHEN 'l' THEN 'L'
      WHEN 'ml' THEN 'mL'
      WHEN 'units' THEN 'units'
      WHEN 'cases' THEN 'cases'
      ELSE NULLIF(trim(`quantity_tested_uom`), '')
    END AS `quantity_tested_uom`,
    CASE WHEN lower(trim(`regulatory_submission_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_submission_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_submission_flag`,
    NULLIF(trim(`remarks`), '') AS `remarks`,
    COALESCE(try_to_date(trim(`retest_date`), 'yyyy-MM-dd'), try_to_date(trim(`retest_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`retest_date`) AS DATE)) AS `retest_date`,
    NULLIF(trim(`storage_condition`), '') AS `storage_condition`,
    NULLIF(trim(`supplier_lot_number`), '') AS `supplier_lot_number`,
    COALESCE(try_to_date(trim(`test_date`), 'yyyy-MM-dd'), try_to_date(trim(`test_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`test_date`) AS DATE)) AS `test_date`,
    NULLIF(trim(`test_method_reference`), '') AS `test_method_reference`,
    NULLIF(trim(`veeva_vault_document_reference`), '') AS `veeva_vault_document_reference`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.quality_certificate_of_analysis
)
SELECT *
FROM typed
QUALIFY `certificate_of_analysis_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `certificate_of_analysis_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- quality.product_complaint ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.quality_product_complaint (
  CONSTRAINT `product_complaint_id_not_null` EXPECT (`product_complaint_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: quality.product_complaint typed and cleaned, one row per product_complaint_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`product_complaint_id`), '') AS BIGINT) AS `product_complaint_id`,
    TRY_CAST(NULLIF(trim(`capa_id`), '') AS BIGINT) AS `capa_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`invoice_id`), '') AS BIGINT) AS `invoice_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`order_id`), '') AS BIGINT) AS `order_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_line_id`), '') AS BIGINT) AS `outbound_order_line_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    NULLIF(trim(`complainant_address`), '') AS `complainant_address`,
    NULLIF(trim(`complainant_country_code`), '') AS `complainant_country_code`,
    NULLIF(trim(`complainant_email`), '') AS `complainant_email`,
    NULLIF(trim(`complainant_name`), '') AS `complainant_name`,
    NULLIF(trim(`complainant_phone`), '') AS `complainant_phone`,
    CASE lower(trim(`complaint_category`))
      WHEN 'foreign_body' THEN 'foreign_body'
      WHEN 'contamination' THEN 'contamination'
      WHEN 'labeling_error' THEN 'labeling_error'
      WHEN 'efficacy_failure' THEN 'efficacy_failure'
      WHEN 'packaging_defect' THEN 'packaging_defect'
      WHEN 'adverse_reaction' THEN 'adverse_reaction'
      ELSE NULLIF(trim(`complaint_category`), '')
    END AS `complaint_category`,
    NULLIF(trim(`complaint_description`), '') AS `complaint_description`,
    NULLIF(trim(`complaint_number`), '') AS `complaint_number`,
    COALESCE(try_to_timestamp(trim(`complaint_received_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`complaint_received_timestamp`) AS TIMESTAMP)) AS `complaint_received_timestamp`,
    CASE lower(trim(`complaint_source`))
      WHEN 'consumer_direct' THEN 'consumer_direct'
      WHEN 'retailer' THEN 'retailer'
      WHEN 'distributor' THEN 'distributor'
      WHEN 'regulatory_agency' THEN 'regulatory_agency'
      WHEN 'social_media' THEN 'social_media'
      WHEN 'call_center' THEN 'call_center'
      ELSE NULLIF(trim(`complaint_source`), '')
    END AS `complaint_source`,
    CASE lower(trim(`complaint_status`))
      WHEN 'open' THEN 'open'
      WHEN 'under_investigation' THEN 'under_investigation'
      WHEN 'pending_lab_analysis' THEN 'pending_lab_analysis'
      WHEN 'resolved' THEN 'resolved'
      WHEN 'closed' THEN 'closed'
      WHEN 'escalated' THEN 'escalated'
      ELSE NULLIF(trim(`complaint_status`), '')
    END AS `complaint_status`,
    NULLIF(trim(`complaint_subcategory`), '') AS `complaint_subcategory`,
    NULLIF(trim(`corrective_action`), '') AS `corrective_action`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    NULLIF(trim(`gtin`), '') AS `gtin`,
    COALESCE(try_to_date(trim(`incident_date`), 'yyyy-MM-dd'), try_to_date(trim(`incident_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`incident_date`) AS DATE)) AS `incident_date`,
    COALESCE(try_to_date(trim(`investigation_completion_date`), 'yyyy-MM-dd'), try_to_date(trim(`investigation_completion_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`investigation_completion_date`) AS DATE)) AS `investigation_completion_date`,
    COALESCE(try_to_date(trim(`investigation_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`investigation_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`investigation_start_date`) AS DATE)) AS `investigation_start_date`,
    CASE lower(trim(`investigation_status`))
      WHEN 'not_started' THEN 'not_started'
      WHEN 'in_progress' THEN 'in_progress'
      WHEN 'lab_testing' THEN 'lab_testing'
      WHEN 'pending_capa' THEN 'pending_capa'
      WHEN 'completed' THEN 'completed'
      ELSE NULLIF(trim(`investigation_status`), '')
    END AS `investigation_status`,
    NULLIF(trim(`lab_analysis_result`), '') AS `lab_analysis_result`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`manufacturing_date`), 'yyyy-MM-dd'), try_to_date(trim(`manufacturing_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`manufacturing_date`) AS DATE)) AS `manufacturing_date`,
    NULLIF(trim(`preventive_action`), '') AS `preventive_action`,
    COALESCE(try_to_date(trim(`purchase_date`), 'yyyy-MM-dd'), try_to_date(trim(`purchase_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`purchase_date`) AS DATE)) AS `purchase_date`,
    NULLIF(trim(`regulatory_agency`), '') AS `regulatory_agency`,
    NULLIF(trim(`regulatory_case_number`), '') AS `regulatory_case_number`,
    COALESCE(try_to_date(trim(`regulatory_report_date`), 'yyyy-MM-dd'), try_to_date(trim(`regulatory_report_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`regulatory_report_date`) AS DATE)) AS `regulatory_report_date`,
    CASE WHEN lower(trim(`regulatory_reportable_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`regulatory_reportable_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `regulatory_reportable_flag`,
    COALESCE(try_to_date(trim(`resolution_date`), 'yyyy-MM-dd'), try_to_date(trim(`resolution_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`resolution_date`) AS DATE)) AS `resolution_date`,
    CASE lower(trim(`resolution_outcome`))
      WHEN 'refund_issued' THEN 'refund_issued'
      WHEN 'replacement_sent' THEN 'replacement_sent'
      WHEN 'no_action_required' THEN 'no_action_required'
      WHEN 'product_recall' THEN 'product_recall'
      WHEN 'investigation_ongoing' THEN 'investigation_ongoing'
      ELSE NULLIF(trim(`resolution_outcome`), '')
    END AS `resolution_outcome`,
    NULLIF(trim(`root_cause`), '') AS `root_cause`,
    COALESCE(try_to_date(trim(`sample_received_date`), 'yyyy-MM-dd'), try_to_date(trim(`sample_received_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`sample_received_date`) AS DATE)) AS `sample_received_date`,
    CASE WHEN lower(trim(`sample_returned_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sample_returned_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sample_returned_flag`,
    CASE lower(trim(`severity_level`))
      WHEN 'critical' THEN 'critical'
      WHEN 'high' THEN 'high'
      WHEN 'medium' THEN 'medium'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`severity_level`), '')
    END AS `severity_level`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.quality_product_complaint
)
SELECT *
FROM typed
QUALIFY `product_complaint_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `product_complaint_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- quality.specification ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.quality_specification (
  CONSTRAINT `specification_id_not_null` EXPECT (`specification_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: quality.specification typed and cleaned, one row per specification_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`specification_id`), '') AS BIGINT) AS `specification_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`inspection_plan_id`), '') AS BIGINT) AS `inspection_plan_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`specification_material_sku_id`), '') AS BIGINT) AS `specification_material_sku_id`,
    TRY_CAST(NULLIF(trim(`specification_sku_id`), '') AS BIGINT) AS `specification_sku_id`,
    TRY_CAST(NULLIF(trim(`superseded_by_specification_id`), '') AS BIGINT) AS `superseded_by_specification_id`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    CASE lower(trim(`category`))
      WHEN 'physical' THEN 'physical'
      WHEN 'chemical' THEN 'chemical'
      WHEN 'microbiological' THEN 'microbiological'
      WHEN 'sensory' THEN 'sensory'
      WHEN 'functional' THEN 'functional'
      WHEN 'safety' THEN 'safety'
      ELSE NULLIF(trim(`category`), '')
    END AS `category`,
    CASE WHEN lower(trim(`coa_inclusion_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`coa_inclusion_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `coa_inclusion_flag`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`critical_quality_attribute_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`critical_quality_attribute_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `critical_quality_attribute_flag`,
    CASE WHEN lower(trim(`customer_requirement_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`customer_requirement_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `customer_requirement_flag`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`lower_specification_limit`), '') AS DECIMAL(18,6)) AS `lower_specification_limit`,
    COALESCE(try_to_date(trim(`next_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`next_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_review_date`) AS DATE)) AS `next_review_date`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`review_frequency_months`), '') AS INT) AS `review_frequency_months`,
    NULLIF(trim(`sampling_plan`), '') AS `sampling_plan`,
    NULLIF(trim(`specification_number`), '') AS `specification_number`,
    CASE lower(trim(`specification_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'under_review' THEN 'under_review'
      WHEN 'approved' THEN 'approved'
      WHEN 'active' THEN 'active'
      WHEN 'superseded' THEN 'superseded'
      WHEN 'obsolete' THEN 'obsolete'
      ELSE NULLIF(trim(`specification_status`), '')
    END AS `specification_status`,
    CASE lower(trim(`specification_type`))
      WHEN 'raw_material' THEN 'raw_material'
      WHEN 'packaging_material' THEN 'packaging_material'
      WHEN 'in_process' THEN 'in_process'
      WHEN 'finished_good' THEN 'finished_good'
      WHEN 'intermediate' THEN 'intermediate'
      WHEN 'bulk' THEN 'bulk'
      ELSE NULLIF(trim(`specification_type`), '')
    END AS `specification_type`,
    CASE WHEN lower(trim(`stability_indicating_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`stability_indicating_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `stability_indicating_flag`,
    TRY_CAST(NULLIF(trim(`target_value`), '') AS DECIMAL(18,6)) AS `target_value`,
    NULLIF(trim(`test_characteristic`), '') AS `test_characteristic`,
    NULLIF(trim(`test_equipment_required`), '') AS `test_equipment_required`,
    NULLIF(trim(`test_frequency`), '') AS `test_frequency`,
    NULLIF(trim(`test_method_reference`), '') AS `test_method_reference`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`upper_specification_limit`), '') AS DECIMAL(18,6)) AS `upper_specification_limit`,
    NULLIF(trim(`veeva_vault_document_reference`), '') AS `veeva_vault_document_reference`,
    NULLIF(trim(`version`), '') AS `version`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.quality_specification
)
SELECT *
FROM typed
QUALIFY `specification_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `specification_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;
